namespace SpriteKind {
    export const EProjectile = SpriteKind.create()
    export const nothing = SpriteKind.create()
    export const EProjectileL = SpriteKind.create()
    export const EProjectile2 = SpriteKind.create()
    export const Vunerable = SpriteKind.create()
    export const Projectile2 = SpriteKind.create()
    export const Vengeful = SpriteKind.create()
    export const Statue2 = SpriteKind.create()
    export const talk = SpriteKind.create()
    export const SecretWall = SpriteKind.create()
    export const LifebloodHive = SpriteKind.create()
    export const LifeSeed = SpriteKind.create()
    export const Statue = SpriteKind.create()
    export const StatusBar = SpriteKind.create()
    export const ZOTE = SpriteKind.create()
    export const talk2 = SpriteKind.create()
}
sprites.onOverlap(SpriteKind.Projectile, SpriteKind.EProjectile2, function (sprite, otherSprite) {
    if (sprites.readDataString(sprite, "Direction") == "L") {
        extraEffects.createSpreadEffectOnAnchor(sprite, myEffect4, 1)
        otherSprite.lifespan = 2000
        otherSprite.setVelocity(-200, -5)
        otherSprite.setKind(SpriteKind.Projectile2)
    } else if (sprites.readDataString(sprite, "Direction") == "R") {
        extraEffects.createSpreadEffectOnAnchor(sprite, myEffect5, 1)
        otherSprite.lifespan = 2000
        otherSprite.setVelocity(200, -5)
        otherSprite.setKind(SpriteKind.Projectile2)
    }
})
