scene.onOverlapTile(SpriteKind.Projectile, assets.tile`myTile7`, function (sprite, location) {
    if (sprites.readDataString(sprite, "Direction") == "L") {
        extraEffects.createSpreadEffectOnAnchor(sprite, myEffect7, 1)
        music.play(music.createSong(hex``), music.PlaybackMode.InBackground)
        tiles.setTileAt(location, assets.tile`myTile26`)
    } else if (sprites.readDataString(sprite, "Direction") == "R") {
        extraEffects.createSpreadEffectOnAnchor(sprite, myEffect8, 1)
        music.play(music.createSong(hex``), music.PlaybackMode.InBackground)
        tiles.setTileAt(location, assets.tile`myTile26`)
    }
})
controller.up.onEvent(ControllerButtonEvent.Released, function () {
    if (mySprite.vy < 0) {
        mySprite.vy = -1
    }
})
