sprites.onOverlap(SpriteKind.Projectile, SpriteKind.LifeSeed, function (sprite, otherSprite) {
    if (sprites.readDataString(sprite, "Direction") == "L") {
        extraEffects.createSpreadEffectOnAnchor(otherSprite, myEffect7, 1)
        HP += 1
        sprites.destroy(otherSprite)
        sprite.setKind(SpriteKind.nothing)
    } else if (sprites.readDataString(sprite, "Direction") == "R") {
        extraEffects.createSpreadEffectOnAnchor(otherSprite, myEffect8, 1)
        sprite.setKind(SpriteKind.nothing)
        sprites.destroy(otherSprite)
        HP += 1
    }
})
