sprites.onOverlap(SpriteKind.Projectile, SpriteKind.Enemy, function (sprite, otherSprite) {
    BossSH += -1
    if (sprites.readDataString(sprite, "Direction") == "L") {
        extraEffects.createSpreadEffectOnAnchor(sprite, myEffect, 1)
        mySprite.x += 4
        sprite.setKind(SpriteKind.nothing)
        music.play(music.createSong(hex``), music.PlaybackMode.InBackground)
    } else if (sprites.readDataString(sprite, "Direction") == "R") {
        extraEffects.createSpreadEffectOnAnchor(sprite, MyEffect2, 1)
        mySprite.x += -4
        sprite.setKind(SpriteKind.nothing)
        music.play(music.createSong(hex``), music.PlaybackMode.InBackground)
    }
})
sprites.onOverlap(SpriteKind.Projectile2, SpriteKind.Enemy, function (sprite, otherSprite) {
    BossSH += -2
    mySprite.x += 4
    music.play(music.createSong(hex``), music.PlaybackMode.InBackground)
    extraEffects.createSpreadEffectOnAnchor(sprite, extraEffects.createSingleColorSpreadEffectData(5, ExtraEffectPresetShape.Spark), 100)
    extraEffects.createSpreadEffectOnAnchor(sprite, extraEffects.createSingleColorSpreadEffectData(4, ExtraEffectPresetShape.Spark), 100)
    sprites.destroy(sprite)
})
