forever(function () {
    if (sprites.readDataNumber(mySprite11, "number") == 1) {
        if (sprites.readDataNumber(mySprite11, "HP") <= 0) {
            mySprite9.setFlag(SpriteFlag.Invisible, true)
            scene.cameraShake(5, 200)
            tiles.setWallAt(tiles.getTileLocation(4, 7), false)
            tiles.setTileAt(tiles.getTileLocation(4, 7), assets.tile`transparency16`)
            tiles.setWallAt(tiles.getTileLocation(4, 8), false)
            tiles.setTileAt(tiles.getTileLocation(4, 8), assets.tile`transparency16`)
            sprites.destroy(mySprite11)
            sprites.changeDataNumberBy(mySprite11, "HP", 10000)
        }
    } else if (sprites.readDataNumber(mySprite11, "number") == 2) {
        if (sprites.readDataNumber(mySprite11, "HP") <= 0) {
            scene.cameraShake(6, 1000)
            mySprite9.setFlag(SpriteFlag.Invisible, true)
            scene.cameraShake(5, 200)
            tiles.setWallAt(tiles.getTileLocation(3, 6), false)
            tiles.setTileAt(tiles.getTileLocation(3, 6), assets.tile`transparency16`)
            tiles.setWallAt(tiles.getTileLocation(3, 7), false)
            tiles.setTileAt(tiles.getTileLocation(3, 7), assets.tile`transparency16`)
            tiles.setWallAt(tiles.getTileLocation(3, 8), false)
            tiles.setTileAt(tiles.getTileLocation(3, 8), assets.tile`transparency16`)
            tiles.setWallAt(tiles.getTileLocation(3, 9), false)
            tiles.setTileAt(tiles.getTileLocation(3, 9), assets.tile`transparency16`)
            tiles.setWallAt(tiles.getTileLocation(3, 10), false)
            tiles.setTileAt(tiles.getTileLocation(3, 10), assets.tile`transparency16`)
            sprites.destroy(mySprite11)
            sprites.changeDataNumberBy(mySprite11, "HP", 10000)
        }
    } else {
    	
    }
})
