forever(function () {
    if (controller.B.isPressed()) {
        if (sprites.readDataNumber(mySprite14, "Arrow") >= 1) {
            Healing = 0
            sprites.setDataNumber(mySprite14, "Arrow", 0)
            characterAnimations.setCharacterAnimationsEnabled(mySprite, true)
            sprites.setDataNumber(mySprite14, "Level", 0)
            sprites.destroy(mySprite14)
            sprites.destroy(mySprite11)
            sprites.destroyAllSpritesOfKind(SpriteKind.Food)
            controller.moveSprite(mySprite, 80, 0)
            timer.after(1000, function () {
                Status.setKind(SpriteKind.Statue2)
                Status2.setKind(SpriteKind.Statue)
            })
        }
    }
    pause(100)
})
